"use client";

import { forwardRef, type ComponentPropsWithoutRef, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { IconMorph, type IconMorphPaths } from "../icon-morph/icon-morph";
import { motionTokens } from "../lib/motion-tokens";
import { MorphingText } from "../morphing-text/morphing-text";
import "../foundation.css";

export type ButtonVariant = "filled" | "bordered" | "text";
export type ButtonTone = "primary" | "secondary" | "success" | "warning" | "danger";
export type ButtonSize = "small" | "medium" | "large";

const baseClass = "inline-flex w-fit items-center justify-center gap-2 whitespace-nowrap rounded-[18px] border font-[inherit] font-[650] leading-none no-underline transition-[opacity,background-color,border-color,color,transform] duration-[var(--duration-fast)] ease-[var(--ease-standard)] [webkit-tap-highlight-color:transparent] focus-visible:outline-2 focus-visible:outline-[var(--focus)] focus-visible:outline-offset-3 disabled:cursor-not-allowed disabled:opacity-[0.48] aria-disabled:cursor-not-allowed aria-disabled:opacity-[0.48] active:not-disabled:translate-y-px";

const sizeClasses: Record<ButtonSize, string> = {
  small: "min-h-10 px-4 text-xs",
  medium: "min-h-[46px] px-5 text-[13px]",
  large: "min-h-[52px] px-6 text-sm",
};

const appearanceClasses: Record<ButtonVariant, Record<ButtonTone, string>> = {
  filled: {
    primary: "border-transparent bg-[var(--primary)] text-[var(--primary-foreground)] hover:bg-[var(--primary-hover)]",
    secondary: "border-transparent bg-[var(--surface-muted)] text-[var(--text)] hover:bg-[color-mix(in_srgb,var(--surface-muted)_82%,var(--text))]",
    success: "border-transparent bg-[var(--surface-muted)] text-[var(--success-surface-foreground)] hover:bg-[var(--success-surface)]",
    warning: "border-transparent bg-[var(--surface-muted)] text-[var(--warning-surface-foreground)] hover:bg-[var(--warning-surface)]",
    danger: "border-transparent bg-[var(--surface-muted)] text-[var(--danger-surface-foreground)] hover:bg-[var(--danger-surface)]",
  },
  bordered: {
    primary: "border-[color-mix(in_srgb,var(--text)_75%,transparent)] bg-[color-mix(in_srgb,var(--surface-muted)_75%,transparent)] text-[var(--text)] hover:border-[var(--text)] hover:bg-[color-mix(in_srgb,var(--primary)_25%,transparent)]",
    secondary: "border-[color-mix(in_srgb,var(--text-secondary)_72%,transparent)] bg-[color-mix(in_srgb,var(--surface-muted)_75%,transparent)] text-[var(--text-secondary)] hover:border-[var(--text-secondary)] hover:bg-[var(--surface-muted)] hover:text-[var(--text)]",
    success: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--success-surface-foreground)] hover:border-[var(--success-surface-foreground)] hover:bg-[var(--success-surface)]",
    warning: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--warning-surface-foreground)] hover:border-[var(--warning-surface-foreground)] hover:bg-[var(--warning-surface)]",
    danger: "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_25%,transparent)] text-[var(--danger-surface-foreground)] hover:border-[var(--danger-surface-foreground)] hover:bg-[var(--danger-surface)]",
  },
  text: {
    primary: "border-transparent bg-transparent text-[var(--text)] hover:bg-[var(--surface-muted)]",
    secondary: "border-transparent bg-transparent text-[var(--text-secondary)] hover:bg-[var(--surface-muted)] hover:text-[var(--text)]",
    success: "border-transparent bg-transparent text-[var(--success-surface-foreground)] hover:bg-[var(--surface-muted)]",
    warning: "border-transparent bg-transparent text-[var(--warning-surface-foreground)] hover:bg-[var(--surface-muted)]",
    danger: "border-transparent bg-transparent text-[var(--danger-surface-foreground)] hover:bg-[var(--surface-muted)]",
  },
};

function classes(variant: ButtonVariant, tone: ButtonTone, size: ButtonSize, className?: string) {
  return [baseClass, sizeClasses[size], appearanceClasses[variant][tone], className]
    .filter(Boolean)
    .join(" ");
}

interface ButtonStyleProps {
  variant?: ButtonVariant;
  tone?: ButtonTone;
  size?: ButtonSize;
}

type OneOrMany<Value> = Value | readonly Value[];

export interface ButtonProps
  extends Omit<ComponentPropsWithoutRef<"button">, "children"> {
  variant?: ButtonVariant;
  tone?: OneOrMany<ButtonTone>;
  size?: ButtonSize;
  children?: ReactNode;
  label?: OneOrMany<string>;
  icon?: OneOrMany<ReactNode>;
  iconPosition?: "start" | "end";
  loading?: OneOrMany<boolean>;
  state?: number;
  iconPaths?: IconMorphPaths;
}

function atState<Value>(value: OneOrMany<Value> | undefined, state: number) {
  if (value === undefined) return undefined;
  if (!Array.isArray(value)) return value as Value;
  return value[Math.min(state, value.length - 1)];
}

function ButtonIcon({ icons, state, paths, spinning }: {
  icons: OneOrMany<ReactNode>;
  state: number;
  paths?: IconMorphPaths;
  spinning?: boolean;
}) {
  const reduceMotion = useReducedMotion() ?? false;
  const values = Array.isArray(icons) ? icons : [icons];
  const current = values[Math.min(state, values.length - 1)];

  if (paths && values.length === 2) {
    return <IconMorph state={state > 0} from={values[0]} to={values[1]} paths={paths} size={18} />;
  }

  return (
    <span className="relative inline-grid size-[18px] place-items-center">
      <AnimatePresence initial={false} mode="popLayout">
        <motion.span
          className="absolute inset-0 grid origin-center place-items-center"
          key={state}
          initial={{ opacity: 0, scale: reduceMotion ? 1 : 0.62 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: reduceMotion ? 1 : 0.62 }}
          transition={reduceMotion ? { duration: 0 } : motionTokens.spring.smooth}
        >
          <motion.span
            className="grid place-items-center [&>svg]:size-[18px]"
            animate={{ rotate: spinning && !reduceMotion ? 360 : 0 }}
            transition={spinning && !reduceMotion
              ? { duration: 0.8, ease: "linear", repeat: Infinity }
              : { duration: 0 }}
          >
            {current}
          </motion.span>
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button({
  variant = "filled",
  tone = "primary",
  size = "medium",
  label,
  icon,
  iconPosition = "start",
  loading = false,
  state = 0,
  iconPaths,
  className,
  children,
  type = "button",
  ...props
}, ref) {
  const activeState = Math.max(0, Math.floor(state));
  const activeTone = atState(tone, activeState) ?? "primary";
  const isLoading = atState(loading, activeState) ?? false;
  const activeIcon = icon
    ? <ButtonIcon icons={icon} state={activeState} paths={iconPaths} spinning={isLoading} />
    : undefined;
  const content = label === undefined
    ? children
    : <MorphingText value={atState(label, activeState) ?? ""} />;
  const iconOnly = activeIcon !== undefined && content == null;

  return (
    <button
      ref={ref}
      {...props}
      type={type}
      aria-busy={isLoading || undefined}
      className={classes(variant, activeTone, size, [
        iconOnly && { small: "w-10 px-0", medium: "w-[46px] px-0", large: "w-[52px] px-0" }[size],
        className,
      ].filter(Boolean).join(" "))}
    >
      {activeIcon && iconPosition === "start" ? <span className="grid shrink-0 place-items-center" aria-hidden="true">{activeIcon}</span> : null}
      {content}
      {activeIcon && iconPosition === "end" ? <span className="grid shrink-0 place-items-center" aria-hidden="true">{activeIcon}</span> : null}
    </button>
  );
});

export interface ButtonLinkProps extends ComponentPropsWithoutRef<"a">, ButtonStyleProps {
  icon?: ReactNode;
  iconPosition?: "start" | "end";
}

export function ButtonLink({
  variant = "filled",
  tone = "primary",
  size = "medium",
  icon,
  iconPosition = "start",
  className,
  children,
  ...props
}: ButtonLinkProps) {
  return (
    <a {...props} className={classes(variant, tone, size, className)}>
      {icon && iconPosition === "start" ? <span className="grid shrink-0 place-items-center [&>svg]:size-[18px]" aria-hidden="true">{icon}</span> : null}
      {children}
      {icon && iconPosition === "end" ? <span className="grid shrink-0 place-items-center [&>svg]:size-[18px]" aria-hidden="true">{icon}</span> : null}
    </a>
  );
}

"use client";

import {
  forwardRef,
  useCallback,
  useId,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ComponentPropsWithoutRef,
  type ReactNode,
} from "react";
import { X } from "lucide-react";
import { Button } from "../button/button";
import "../foundation.css";

export type TextareaVariant = "filled" | "bordered";
export type TextareaResize = "none" | "vertical" | "both";

interface CharacterItem {
  id: number;
  value: string;
  isNew: boolean;
  delay: number;
}

export interface TextareaProps extends Omit<
  ComponentPropsWithoutRef<"textarea">,
  "value" | "defaultValue"
> {
  label?: ReactNode;
  hint?: ReactNode;
  error?: ReactNode;
  prefixIcon?: ReactNode;
  suffixIcon?: ReactNode;
  suffixControl?: ReactNode;
  variant?: TextareaVariant;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  clearable?: boolean;
  clearLabel?: string;
  /** Duration, in milliseconds, of the typed-character reveal. */
  animationDuration?: number;
  /** Expands the field to fit its current content. */
  autoResize?: boolean;
  /** Native resize behavior when autoResize is disabled. */
  resize?: TextareaResize;
}

export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>(function Textarea({
  id,
  label,
  hint,
  error,
  prefixIcon,
  suffixIcon,
  suffixControl,
  variant = "filled",
  value,
  defaultValue = "",
  onValueChange,
  clearable = true,
  clearLabel = "Clear text",
  animationDuration,
  autoResize = false,
  resize = "vertical",
  disabled,
  required,
  className,
  style,
  rows = 4,
  onChange,
  "aria-describedby": ariaDescribedBy,
  ...props
}, forwardedRef) {
  const generatedId = useId();
  const textareaId = id ?? generatedId;
  const hintId = `${textareaId}-hint`;
  const errorId = `${textareaId}-error`;
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const overlayRef = useRef<HTMLDivElement>(null);
  const [internalValue, setInternalValue] = useState(defaultValue);
  const [caretOffset, setCaretOffset] = useState(0);
  const [visualScrollTop, setVisualScrollTop] = useState(0);
  const currentValue = value ?? internalValue;
  const [characterState, setCharacterState] = useState<{
    value: string;
    items: CharacterItem[];
    nextId: number;
  }>(() => ({
    value: currentValue,
    items: Array.from(currentValue).map((character, index) => ({
      id: index,
      value: character,
      isNew: false,
      delay: 0,
    })),
    nextId: currentValue.length,
  }));
  const describedBy = [ariaDescribedBy, error ? errorId : hint ? hintId : undefined]
    .filter(Boolean)
    .join(" ") || undefined;
  const appearanceClass = error
    ? "border-[var(--danger-surface-foreground)] bg-[color-mix(in_srgb,var(--danger-surface)_36%,var(--surface))] focus-within:border-[var(--danger-surface-foreground)]"
    : variant === "filled"
      ? "border-transparent bg-[var(--surface-muted)] focus-within:border-[var(--focus)]"
      : "border-[var(--border)] bg-[color-mix(in_srgb,var(--surface-muted)_58%,var(--surface))] focus-within:border-[var(--focus)]";

  if (characterState.value !== currentValue) {
    const previousItems = characterState.items;
    const previousCharacters = previousItems.map((item) => item.value);
    const nextCharacters = Array.from(currentValue);
    const sequenceLengths = Array.from(
      { length: previousCharacters.length + 1 },
      () => Array<number>(nextCharacters.length + 1).fill(0),
    );

    for (let previousIndex = previousCharacters.length - 1; previousIndex >= 0; previousIndex -= 1) {
      for (let nextIndex = nextCharacters.length - 1; nextIndex >= 0; nextIndex -= 1) {
        sequenceLengths[previousIndex][nextIndex] = previousCharacters[previousIndex] === nextCharacters[nextIndex]
          ? (sequenceLengths[previousIndex + 1][nextIndex + 1] ?? 0) + 1
          : Math.max(
              sequenceLengths[previousIndex + 1][nextIndex] ?? 0,
              sequenceLengths[previousIndex][nextIndex + 1] ?? 0,
            );
      }
    }

    const items: CharacterItem[] = [];
    let nextId = characterState.nextId;
    let previousIndex = 0;
    let nextIndex = 0;
    let insertionIndex = 0;

    while (nextIndex < nextCharacters.length) {
      if (
        previousIndex < previousCharacters.length &&
        previousCharacters[previousIndex] === nextCharacters[nextIndex]
      ) {
        items.push({ ...previousItems[previousIndex], isNew: false, delay: 0 });
        previousIndex += 1;
        nextIndex += 1;
      } else if (
        previousIndex < previousCharacters.length &&
        (sequenceLengths[previousIndex + 1][nextIndex] ?? 0) >=
          (sequenceLengths[previousIndex][nextIndex + 1] ?? 0)
      ) {
        previousIndex += 1;
      } else {
        items.push({
          id: nextId,
          value: nextCharacters[nextIndex],
          isNew: true,
          delay: insertionIndex * 25,
        });
        nextId += 1;
        nextIndex += 1;
        insertionIndex += 1;
      }
    }

    setCharacterState({ value: currentValue, items, nextId });
  }

  const resizeToContent = useCallback(() => {
    const element = textareaRef.current;
    if (!autoResize || !element) return;
    element.style.height = "auto";
    element.style.height = `${element.scrollHeight}px`;
  }, [autoResize]);

  const syncCaretOffset = useCallback(() => {
    const element = textareaRef.current;
    if (!element || typeof window === "undefined") return;

    const computed = window.getComputedStyle(element);
    const mirror = document.createElement("div");
    const marker = document.createElement("span");
    const copiedStyles = [
      "boxSizing",
      "fontFamily",
      "fontSize",
      "fontWeight",
      "fontStyle",
      "letterSpacing",
      "lineHeight",
      "textTransform",
      "textIndent",
      "wordSpacing",
      "tabSize",
    ] as const;

    for (const property of copiedStyles) {
      mirror.style[property] = computed[property];
    }

    mirror.style.position = "absolute";
    mirror.style.visibility = "hidden";
    mirror.style.pointerEvents = "none";
    mirror.style.top = "0";
    mirror.style.left = "-9999px";
    mirror.style.width = `${element.clientWidth}px`;
    mirror.style.padding = "0";
    mirror.style.border = "0";
    mirror.style.whiteSpace = "pre-wrap";
    mirror.style.overflowWrap = "break-word";
    mirror.style.wordBreak = "break-word";
    mirror.textContent = element.value.slice(0, element.selectionStart ?? 0);
    marker.textContent = "\u200b";
    mirror.appendChild(marker);
    document.body.appendChild(mirror);

    const markerTop = marker.getBoundingClientRect().top - mirror.getBoundingClientRect().top;
    const lineHeight = Number.parseFloat(computed.lineHeight) || 21;
    setCaretOffset(Math.max(0, element.offsetTop + markerTop - element.scrollTop - (40 - lineHeight) / 2));
    mirror.remove();
  }, []);

  useImperativeHandle(forwardedRef, () => textareaRef.current as HTMLTextAreaElement);

  useLayoutEffect(() => {
    resizeToContent();
    syncCaretOffset();
  }, [currentValue, resizeToContent, syncCaretOffset]);

  const updateValue = (nextValue: string) => {
    if (value === undefined) setInternalValue(nextValue);
    onValueChange?.(nextValue);
  };

  const clear = () => {
    updateValue("");
    textareaRef.current?.focus();
    requestAnimationFrame(syncCaretOffset);
  };

  const settleCharacter = (characterId: number) => {
    setCharacterState((currentState) => {
      const item = currentState.items.find((character) => character.id === characterId);
      if (!item?.isNew) return currentState;

      return {
        ...currentState,
        items: currentState.items.map((character) =>
          character.id === characterId
            ? { ...character, isNew: false, delay: 0 }
            : character,
        ),
      };
    });
  };

  const hasValue = currentValue.length > 0;
  const hasAnimatingCharacters = characterState.items.some((item) => item.isNew);

  return (
    <div className={["grid w-full gap-2", className].filter(Boolean).join(" ")}>
      {label ? <label className="text-[13px] leading-[1.4] font-[620] text-[var(--text)]" htmlFor={textareaId}>{label}{required ? <span aria-hidden="true"> *</span> : null}</label> : null}
      <div className="grid min-w-0 grid-cols-[minmax(0,1fr)_40px] items-start gap-1">
        <div
          className={[
            "relative grid min-w-0 grid-cols-[auto_minmax(0,1fr)_auto] items-start gap-2 rounded-[18px] border text-[var(--text)] transition-[background-color,border-color,opacity] duration-[var(--duration-fast)] ease-[var(--ease-standard)] motion-reduce:duration-[0.01ms]",
            "p-3.5",
            appearanceClass,
            disabled && "cursor-not-allowed opacity-[0.52]",
          ].filter(Boolean).join(" ")}
          style={animationDuration
            ? ({ "--textarea-character-duration": `${animationDuration}ms` } as CSSProperties)
            : undefined}
        >
          {prefixIcon ? <span className="grid shrink-0 place-items-center pt-0.5 text-[var(--text-secondary)] [&>svg]:size-[18px]" aria-hidden="true">{prefixIcon}</span> : null}
          <div className="relative min-h-[24px] min-w-0 overflow-hidden">
            <div
              ref={overlayRef}
              className="pointer-events-none absolute inset-0 z-[1] overflow-hidden whitespace-pre-wrap break-words text-[14px] leading-[1.5] tracking-[-0.01em] text-[var(--text)] [font-feature-settings:'kern'_0,'liga'_0,'clig'_0] [font-kerning:none] [font-variant-ligatures:none] select-none"
              aria-hidden="true"
            >
              <span className="block will-change-transform" style={{ transform: `translateY(${-visualScrollTop}px)` }}>
                {hasAnimatingCharacters
                  ? characterState.items.map((item) => (
                      <span
                        className={item.isNew ? "inline-block animate-[sya-input-character-reveal_var(--textarea-character-duration,600ms)_cubic-bezier(0.16,1,0.3,1)_both] will-change-[transform,opacity] motion-reduce:inline motion-reduce:animate-none motion-reduce:transform-none motion-reduce:will-change-auto" : undefined}
                        key={item.id}
                        onAnimationEnd={() => settleCharacter(item.id)}
                        style={{ animationDelay: item.delay ? `${item.delay}ms` : undefined }}
                      >
                        {item.value === " " ? "\u00a0" : item.value}
                      </span>
                    ))
                  : characterState.items.map((item) => item.value).join("")}
              </span>
            </div>
            <textarea
              {...props}
              ref={textareaRef}
              id={textareaId}
              className={[
                "relative z-[2] min-h-[24px] w-full min-w-0 border-0 bg-transparent p-0 text-[14px] leading-[1.5] tracking-[-0.01em] text-[var(--text)] caret-[var(--focus)] outline-none placeholder:text-[var(--text-secondary)] placeholder:opacity-100 [font-feature-settings:'kern'_0,'liga'_0,'clig'_0] [font-kerning:none] [font-variant-ligatures:none] disabled:cursor-not-allowed",
                hasValue && "!text-transparent ![-webkit-text-fill-color:transparent] ![text-shadow:none]",
                autoResize ? "resize-none overflow-hidden" : resize === "both" ? "resize" : resize === "vertical" ? "resize-y" : "resize-none",
              ].filter(Boolean).join(" ")}
              style={hasValue ? {
                ...style,
                color: "transparent",
                WebkitTextFillColor: "transparent",
              } : style}
              value={currentValue}
              rows={rows}
              disabled={disabled}
              required={required}
              aria-invalid={Boolean(error) || undefined}
              aria-describedby={describedBy}
              onChange={(event) => {
                updateValue(event.currentTarget.value);
                onChange?.(event);
                requestAnimationFrame(() => {
                  resizeToContent();
                  syncCaretOffset();
                });
              }}
              onSelect={(event) => {
                props.onSelect?.(event);
                requestAnimationFrame(syncCaretOffset);
              }}
              onKeyUp={(event) => {
                props.onKeyUp?.(event);
                requestAnimationFrame(syncCaretOffset);
              }}
              onClick={(event) => {
                props.onClick?.(event);
                requestAnimationFrame(syncCaretOffset);
              }}
              onFocus={(event) => {
                props.onFocus?.(event);
                requestAnimationFrame(syncCaretOffset);
              }}
              onScroll={(event) => {
                setVisualScrollTop(event.currentTarget.scrollTop);
                props.onScroll?.(event);
                requestAnimationFrame(syncCaretOffset);
              }}
            />
          </div>
          <span className="inline-flex min-w-0 items-center gap-2 pt-0.5">
            {suffixIcon ? <span className="grid shrink-0 place-items-center text-[var(--text-secondary)] [&>svg]:size-[18px]" aria-hidden="true">{suffixIcon}</span> : null}
            {suffixControl ? <span className="inline-flex shrink-0 items-center">{suffixControl}</span> : null}
          </span>
        </div>
        {clearable && hasValue && !disabled ? (
          <Button
            className="size-10 p-0 transition-transform duration-[var(--duration-fast)] ease-[var(--ease-standard)]"
            style={{ transform: `translateY(${caretOffset}px)` }}
            variant="text"
            tone="secondary"
            size="small"
            icon={<X />}
            aria-label={clearLabel}
            onClick={clear}
          />
        ) : <span aria-hidden="true" />}
      </div>
      {error || hint || typeof props.maxLength === "number" ? (
        <div className="-mt-0.5 flex min-w-0 items-start justify-between gap-3">
          {error ? <p className="m-0 min-w-0 text-xs leading-[1.5] text-[var(--danger-surface-foreground)]" id={errorId}>{error}</p> : hint ? <p className="m-0 min-w-0 text-xs leading-[1.5] text-[var(--text-secondary)]" id={hintId}>{hint}</p> : <span />}
          {typeof props.maxLength === "number" ? (
            <p className="m-0 shrink-0 text-right text-xs leading-[1.5] text-[var(--text-secondary)]" aria-live="polite">
              {currentValue.length} / {props.maxLength}
            </p>
          ) : null}
        </div>
      ) : null}
    </div>
  );
});

"use client";

import type { CSSProperties, ReactNode } from "react";
import { motion, useReducedMotion } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export interface IconMorphPaths {
  from: string[];
  to: string[];
}

export interface IconMorphProps {
  state: boolean;
  from: ReactNode;
  to: ReactNode;
  paths?: IconMorphPaths;
  size?: number;
  strokeWidth?: number;
  className?: string;
  style?: CSSProperties;
}

const pathCommands = (path: string) => path.match(/[a-z]/gi)?.join("") ?? "";
const pathValues = (path: string) =>
  path.match(/-?(?:\d*\.)?\d+(?:e[-+]?\d+)?/gi)?.length ?? 0;

function pathsCanMorph(paths?: IconMorphPaths) {
  if (!paths || paths.from.length === 0 || paths.from.length !== paths.to.length) {
    return false;
  }

  return paths.from.every(
    (path, index) =>
      pathCommands(path) === pathCommands(paths.to[index] ?? "") &&
      pathValues(path) === pathValues(paths.to[index] ?? ""),
  );
}

export const iconMorphPresets = {
  menuClose: {
    from: ["M4 7L20 7", "M4 12L20 12", "M4 17L20 17"],
    to: ["M6 6L18 18", "M12 12L12 12", "M18 6L6 18"],
  },
  plusCheck: {
    from: ["M12 5L12 19", "M5 12L19 12"],
    to: ["M5 13L10 18", "M10 18L19 7"],
  },
  playPause: {
    from: ["M7 5L12 8L12 16L7 19Z", "M12 8L19 12L12 16L12 8Z"],
    to: ["M7 5L11 5L11 19L7 19Z", "M14 5L18 5L18 19L14 19Z"],
  },
  chevron: {
    from: ["M6 9L12 15L18 9"],
    to: ["M9 6L15 12L9 18"],
  },
} satisfies Record<string, IconMorphPaths>;

export function IconMorph({
  state,
  from,
  to,
  paths,
  size = 24,
  strokeWidth = 1.75,
  className,
  style,
}: IconMorphProps) {
  const reduceMotion = useReducedMotion() ?? false;
  const canMorph = pathsCanMorph(paths);
  const rootStyle = {
    ...style,
    "--icon-morph-size": `${size}px`,
  } as CSSProperties;

  if (canMorph && paths) {
    return (
      <motion.svg
        className={["relative inline-grid size-[var(--icon-morph-size)] shrink-0 place-items-center align-middle text-[inherit]", className].filter(Boolean).join(" ")}
        style={rootStyle}
        viewBox="0 0 24 24"
        width={size}
        height={size}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
        focusable="false"
      >
        {paths.from.map((path, index) => (
          <motion.path
            key={index}
            initial={false}
            animate={{ d: state ? paths.to[index] : path }}
            transition={reduceMotion ? { duration: 0 } : motionTokens.spring.smooth}
          />
        ))}
      </motion.svg>
    );
  }

  const hidden = {
    opacity: 0,
    scale: reduceMotion ? 1 : 0.62,
  };
  const visible = { opacity: 1, scale: 1 };
  const transition = reduceMotion
    ? { duration: 0 }
    : {
        scale: motionTokens.spring.smooth,
        opacity: {
          duration: motionTokens.duration.fast,
          ease: motionTokens.ease.standard,
        },
      };

  return (
    <span
      className={["relative inline-grid size-[var(--icon-morph-size)] shrink-0 place-items-center align-middle text-[inherit]", className].filter(Boolean).join(" ")}
      style={rootStyle}
      aria-hidden="true"
    >
      <motion.span
        className="absolute inset-0 grid origin-center place-items-center will-change-[transform,opacity] motion-reduce:will-change-auto [&>svg]:size-full"
        initial={false}
        animate={state ? hidden : visible}
        transition={transition}
      >
        {from}
      </motion.span>
      <motion.span
        className="absolute inset-0 grid origin-center place-items-center will-change-[transform,opacity] motion-reduce:will-change-auto [&>svg]:size-full"
        initial={false}
        animate={state ? visible : hidden}
        transition={transition}
      >
        {to}
      </motion.span>
    </span>
  );
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";
import {
  animate,
  motion,
  useMotionValue,
  useReducedMotion,
  type HTMLMotionProps,
} from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

type SpanProps = Omit<HTMLMotionProps<"span">, "children">;

export interface MorphingTextProps extends SpanProps {
  value: string;
}

interface TextDifference {
  prefix: string;
  previous: string;
  current: string;
  suffix: string;
}

function compareText(previous: string, current: string): TextDifference {
  const previousCharacters = Array.from(previous);
  const currentCharacters = Array.from(current);
  const sharedLength = Math.min(previousCharacters.length, currentCharacters.length);
  let prefixLength = 0;

  while (
    prefixLength < sharedLength &&
    previousCharacters[prefixLength] === currentCharacters[prefixLength]
  ) {
    prefixLength += 1;
  }

  let previousEnd = previousCharacters.length;
  let currentEnd = currentCharacters.length;

  while (
    previousEnd > prefixLength &&
    currentEnd > prefixLength &&
    previousCharacters[previousEnd - 1] === currentCharacters[currentEnd - 1]
  ) {
    previousEnd -= 1;
    currentEnd -= 1;
  }

  return {
    prefix: currentCharacters.slice(0, prefixLength).join(""),
    previous: previousCharacters.slice(prefixLength, previousEnd).join(""),
    current: currentCharacters.slice(prefixLength, currentEnd).join(""),
    suffix: currentCharacters.slice(currentEnd).join(""),
  };
}

export function MorphingText({
  value,
  className,
  style,
  ...props
}: MorphingTextProps) {
  const [change, setChange] = useState({ previous: value, current: value });
  const measureRef = useRef<HTMLSpanElement>(null);
  const firstMeasurement = useRef(true);
  const reduceMotion = useReducedMotion() ?? false;
  const width = useMotionValue(0);

  if (change.current !== value) {
    setChange({ previous: change.current, current: value });
  }

  const difference = compareText(change.previous, change.current);
  const changedText = difference.current;
  const hasChangedText = Boolean(difference.previous || changedText);

  useLayoutEffect(() => {
    const measure = measureRef.current;
    if (!measure) return;
    let stopAnimation = () => {};

    const resize = () => {
      const nextWidth = measure.getBoundingClientRect().width;
      stopAnimation();

      if (firstMeasurement.current || reduceMotion) {
        firstMeasurement.current = false;
        width.jump(nextWidth);
        return;
      }

      const controls = animate(width, nextWidth, motionTokens.spring.smooth);
      stopAnimation = () => controls.stop();
    };

    resize();
    const observer = new ResizeObserver(resize);
    observer.observe(measure);
    return () => {
      stopAnimation();
      observer.disconnect();
    };
  }, [changedText, reduceMotion, width]);

  return (
    <motion.span
      {...props}
      className={["relative inline-block whitespace-nowrap", className].filter(Boolean).join(" ")}
      style={style}
      aria-live="polite"
    >
      <span className="absolute size-px overflow-hidden [clip:rect(0,0,0,0)] [clip-path:inset(50%)] whitespace-nowrap">{value}</span>
      <span className="inline-flex items-baseline whitespace-nowrap" aria-hidden="true">
        <span className="whitespace-pre">{difference.prefix}</span>
        <motion.span className="relative inline-grid min-w-0 overflow-hidden text-start" style={{ width }}>
          {hasChangedText ? (
            <motion.span
              key={change.current}
              className="absolute top-0 left-0 flex w-max flex-col [line-height:inherit] will-change-transform"
              initial={{
                transform: reduceMotion ? "translateY(-50%)" : "translateY(0%)",
              }}
              animate={{ transform: "translateY(-50%)" }}
              transition={reduceMotion ? { duration: 0 } : motionTokens.spring.smooth}
            >
              <span className="block h-[1lh] whitespace-pre">
                {difference.previous || "\u00a0"}
              </span>
              <span className="block h-[1lh] whitespace-pre">{changedText || "\u00a0"}</span>
            </motion.span>
          ) : null}
          <span className="col-[1] row-[1] invisible inline-block justify-self-start whitespace-pre pointer-events-none">{changedText || "\u00a0"}</span>
          <span ref={measureRef} className="absolute invisible w-max whitespace-pre pointer-events-none">
            {changedText}
          </span>
        </motion.span>
        <span className="whitespace-pre">{difference.suffix}</span>
      </span>
    </motion.span>
  );
}
